<script setup lang="ts">
import { computed, onMounted, shallowRef } from 'vue'
import { useLibrary } from '@/composables/useLibrary'
const props = defineProps<{ csrfToken: string; username: string }>()
const sourceName = shallowRef('Movies'); const sourcePath = shallowRef('/media/movies'); const query = shallowRef('')
const { sourceItems, mediaItems, jobItems, error, hasSources, refresh, createSource, scan: queueScan } = useLibrary(() => props.csrfToken)
const activeJobs = computed(() => jobItems.value.filter(job => job.state === 'queued' || job.state === 'running'))
async function add() { await createSource(sourceName.value, sourcePath.value) }
async function scan(id: number) { await queueScan(id) }
async function search() { await refresh(query.value) }
onMounted(refresh)
</script>
<template><main class="library-workspace"><header class="library-header"><div><p class="eyebrow">Library discovery</p><h1>Films, before the metadata.</h1><p>Signed in as {{ props.username }}. Scans are read-only.</p></div><button type="button" @click="refresh(query)">Refresh</button></header><p v-if="error" class="library-error">{{ error }}</p><section v-if="!hasSources" class="source-onboarding"><p class="eyebrow">First source</p><h2>Point MediaGrap at a mounted movie folder.</h2><p>Only directories within the server’s configured media roots can be added.</p><form @submit.prevent="add"><label>Name<input v-model="sourceName" required /></label><label>Container path<input v-model="sourcePath" required /></label><button type="submit">Add media source</button></form></section><template v-else><section class="source-strip"><article v-for="source in sourceItems" :key="source.id"><p>{{ source.name }}</p><strong>{{ source.itemCount }} films</strong><small>{{ source.rootPath }}</small><button type="button" @click="scan(source.id)">Scan source</button></article></section><section class="catalog"><header><div><p class="eyebrow">Indexed films</p><h2>{{ mediaItems.length }} visible</h2></div><form @submit.prevent="search"><input v-model="query" placeholder="Search title hints" /><button>Search</button></form></header><p v-if="activeJobs.length" class="job-note">{{ activeJobs[0].message }} · {{ activeJobs[0].progressCurrent }} files indexed</p><ol v-if="mediaItems.length" class="movie-list"><li v-for="item in mediaItems" :key="item.id"><span class="film-mark">{{ item.titleHint.slice(0,1) }}</span><div><strong>{{ item.titleHint }}</strong><p>{{ item.relativePath }}</p></div><span>{{ item.yearHint ?? '—' }}</span><small>{{ item.sidecars.length }} sidecars</small></li></ol><p v-else class="empty-state">No film files are indexed yet. Start a scan from a source above.</p></section></template></main></template>
<style scoped>.library-workspace{max-width:75rem;margin:auto;padding:clamp(1.25rem,4vw,4rem)}.library-header,.catalog>header{display:flex;justify-content:space-between;gap:1rem;align-items:end}.library-header h1{margin:.35rem 0;font:500 clamp(2.5rem,6vw,5rem)/.9 var(--font-display);letter-spacing:-.07em}.library-header p{color:var(--ink-600)}button{min-height:2.6rem;padding:.5rem .8rem;border:1px solid var(--ink-700);border-radius:.45rem;background:var(--ink-900);color:white;font-weight:700;cursor:pointer}.source-onboarding,.catalog{margin-top:2rem;padding:clamp(1.2rem,3vw,2.4rem);border:1px solid var(--mist-300);border-radius:1rem;background:var(--paper)}h2{margin:.35rem 0;font:500 2rem var(--font-display)}form{display:grid;gap:.8rem;margin-top:1.3rem}label{display:grid;gap:.3rem;font-size:.8rem;font-weight:700}input{min-height:2.6rem;padding:.5rem .7rem;border:1px solid var(--mist-300);border-radius:.4rem}.source-strip{display:grid;grid-template-columns:repeat(auto-fit,minmax(15rem,1fr));gap:1rem;margin-top:2rem}.source-strip article{display:grid;gap:.45rem;padding:1.1rem;border:1px solid var(--mist-300);border-radius:.75rem;background:var(--paper)}.source-strip p,.source-strip small{margin:0;color:var(--ink-600)}.source-strip button{justify-self:start;margin-top:.5rem}.catalog>header form{display:flex;margin:0}.catalog>header input{min-width:12rem}.job-note,.library-error{padding:.7rem;border-radius:.4rem;background:var(--water-100);color:var(--ink-800)}.movie-list{display:grid;gap:.3rem;padding:0;list-style:none}.movie-list li{display:grid;grid-template-columns:auto 1fr auto auto;gap:.9rem;align-items:center;padding:1rem 0;border-top:1px solid var(--mist-200)}.movie-list p{margin:.25rem 0 0;color:var(--ink-600);font-size:.85rem}.film-mark{display:grid;width:2.3rem;height:2.3rem;place-items:center;border-radius:.45rem;background:var(--ink-900);color:var(--amber-400);font:1.1rem var(--font-display)}.empty-state{padding:2rem 0;color:var(--ink-600)}@media(max-width:600px){.library-header,.catalog>header{align-items:stretch;flex-direction:column}.library-header button{width:100%}.catalog>header form{width:100%}.catalog>header input{min-width:0;flex:1}.movie-list li{grid-template-columns:auto 1fr auto}.movie-list small{grid-column:2;color:var(--ink-600)}}</style>
